import {JOURNAL_KEY,validateEntry,parseBackup} from './journal-model.mjs';
const form=document.querySelector('#journal-form');
const status=document.querySelector('#journal-status');
const list=document.querySelector('#journal-entries');
let entries=[];let healthy=true;
const tell=text=>{status.textContent=text;};
try{const raw=localStorage.getItem(JOURNAL_KEY);if(raw)entries=parseBackup(raw);}catch{healthy=false;tell('อ่านพื้นที่เก็บบันทึกไม่ได้ ระบบหยุดการเขียนทับไว้ กรุณาตรวจการอนุญาตพื้นที่เก็บข้อมูลของเบราว์เซอร์');}
const node=(tag,text,cls)=>{const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el;};
function persist(next){if(!healthy)throw Error('ยังบันทึกไม่ได้ เพราะอ่านข้อมูลเดิมไม่สำเร็จ');if(next.length>500)throw Error('บันทึกได้สูงสุด 500 เรื่อง โปรดส่งออกไฟล์สำรอง');const json=JSON.stringify({version:1,entries:next});try{localStorage.setItem(JOURNAL_KEY,json);}catch{throw Error('บันทึกไม่สำเร็จ พื้นที่เก็บข้อมูลอาจเต็มหรือถูกปิด กรุณาส่งออกไฟล์สำรอง');}entries=next;render();}
function reset(){form.reset();form.elements.id.value='';document.querySelector('#editor-title').textContent='เขียนบันทึกใหม่';}
function edit(entry){for(const key of ['id','title','matchDate','opponent','score','mood','motm','body','moment','image'])form.elements[key].value=entry[key];document.querySelector('#editor-title').textContent='แก้ไขบันทึก';form.elements.title.focus();tell('กำลังแก้ไขบันทึกเดิม กดบันทึกเพื่อยืนยันการเปลี่ยนแปลง');}
function render(){
 document.querySelector('#entry-count').textContent=entries.length;
 document.querySelector('#moment-count').textContent=entries.filter(e=>e.moment).length;
 list.replaceChildren();const q=document.querySelector('#journal-search').value.trim().toLocaleLowerCase();const mood=document.querySelector('#mood-filter').value;
 const filtered=entries.filter(e=>(mood==='all'||e.mood===mood)&&[e.title,e.opponent,e.body,e.moment,e.motm].join(' ').toLocaleLowerCase().includes(q)).sort((a,b)=>b.matchDate.localeCompare(a.matchDate)||b.createdAt.localeCompare(a.createdAt));
 if(!filtered.length){list.append(node('p',entries.length?'ไม่พบบันทึกตามตัวกรอง ลองเปลี่ยนคำค้นครับ':'ยังไม่มีบันทึกที่บันทึกไว้ เริ่มจากแมตช์ที่โอมเลือก หรือเขียนเรื่องใหม่ได้เลยครับ','journal-empty'));return;}
 for(const e of filtered){const card=node('article',undefined,'journal-entry');const date=new Intl.DateTimeFormat('th-TH',{dateStyle:'medium',timeZone:'UTC'}).format(new Date(e.matchDate+'T00:00:00Z'));card.append(node('small',date+' · เชลซี พบ '+e.opponent),node('h3',e.title));if(e.mood)card.append(node('span',e.mood,'entry-tag'));if(e.score)card.append(node('p','สกอร์ที่บันทึก: '+e.score));if(e.image){const img=node('img');img.src='assets/images/'+e.image;img.alt='ภาพจากคอลเลกชันประกอบบันทึก';img.loading='lazy';card.append(img);}card.append(node('p',e.body));if(e.motm)card.append(node('p','นักเตะที่ผมประทับใจ: '+e.motm));if(e.moment)card.append(node('blockquote',e.moment));const button=node('button','แก้ไขบันทึก','journal-secondary');button.type='button';button.addEventListener('click',()=>edit(e));card.append(button);list.append(card);}
}
form.addEventListener('submit',event=>{event.preventDefault();try{const value=Object.fromEntries(new FormData(form));const previous=entries.find(e=>e.id===value.id);const now=new Date().toISOString();const entry=validateEntry({...value,id:previous?.id||crypto.randomUUID(),createdAt:previous?.createdAt||now,updatedAt:now});persist(previous?entries.map(e=>e.id===entry.id?entry:e):[...entries,entry]);reset();tell('บันทึกในเบราว์เซอร์นี้แล้ว ยังไม่ได้เผยแพร่หรือซิงก์ข้ามเครื่อง');}catch(error){tell(error.message);}});
document.querySelector('#cancel-edit').addEventListener('click',()=>{reset();tell('ล้างเฉพาะแบบฟอร์มแล้ว บันทึกที่บันทึกไว้ยังอยู่');});
document.querySelector('#start-memory').addEventListener('click',()=>{if([...form.querySelectorAll('input:not([type=hidden]),textarea')].some(e=>e.value)&&!confirm('ต้องการแทนค่าที่ยังไม่บันทึกในแบบฟอร์มด้วยข้อมูลนัดชิงสโมสรโลกไหมครับ?'))return;reset();form.elements.title.value='วันที่เชลซีเป็นแชมป์โลก';form.elements.matchDate.value='2025-07-13';form.elements.opponent.value='Paris Saint-Germain';form.elements.score.value='เชลซี 3–0 PSG';form.elements.body.focus();tell('ใส่ข้อมูลการแข่งขันให้แล้ว กรุณาเขียนความรู้สึกของโอมก่อนกดบันทึก');});
document.querySelector('#journal-search').addEventListener('input',render);document.querySelector('#mood-filter').addEventListener('change',render);
document.querySelector('#export-journal').addEventListener('click',()=>{if(!healthy){tell('อ่านข้อมูลเดิมไม่ได้ จึงยังส่งออกไฟล์สำรองที่สมบูรณ์ไม่ได้');return;}const blob=new Blob([JSON.stringify({version:1,entries},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=node('a');a.href=url;a.download='ohm-blue-journal-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);tell('สร้างไฟล์สำรองแล้ว เก็บไฟล์ไว้เพื่อย้ายเครื่องหรือนำเข้าภายหลัง');});
document.querySelector('#import-journal').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>2_000_000)throw Error('ไฟล์ใหญ่เกิน 2 MB');const imported=parseBackup(await file.text());const known=new Set(entries.map(e=>e.id));const added=imported.filter(e=>!known.has(e.id));persist([...entries,...added]);tell('นำเข้า '+added.length+' เรื่อง โดยไม่ทับบันทึกเดิมที่มีรหัสเดียวกัน');}catch(error){tell('นำเข้าไม่สำเร็จ: '+error.message);}event.target.value='';});
render();
